//! ⏱️ Public source accessor work agrees with the neutral corpus and independent serde values.
pub use semio_framework_value_native_owned::*;
#[test]fn source_accessor_work_matches_neutral_cases_and_serde_values(){use crate::owned::tree::{NativeSourceAccess,NativeValueSource};let f:serde_json::Value=serde_json::from_str(include_str!("../../../🌳️value/📖️source/🧪️fixtures/⏱️access/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){let operation=row["operation"].as_str().unwrap();let index=row["index"].as_u64().unwrap_or(0) as usize;let value=match operation{"Boolean"=>DslValue::Bool(row["value"].as_bool().unwrap()),"Number"=>DslValue::Number(crate::Number::UInt(row["value"].as_u64().unwrap())),"SequenceChild"=>DslValue::Array(row["value"].as_array().unwrap().iter().map(|x|DslValue::Number(crate::Number::UInt(x.as_u64().unwrap()))).collect()),"RecordChild"=>DslValue::Object(row["value"].as_object().unwrap().iter().map(|(k,v)|(k.clone(),DslValue::Number(crate::Number::UInt(v.as_u64().unwrap())))).collect()),_=>panic!("unknown fixture operation")};let access=match operation{"Boolean"=>NativeSourceAccess::Boolean,"Number"=>NativeSourceAccess::Number,"SequenceChild"=>NativeSourceAccess::SequenceChild(index),"RecordChild"=>NativeSourceAccess::RecordChild(index),_=>unreachable!()};assert_eq!(value.accessor_work_demand(access).unwrap(),row["work"].as_u64().unwrap());if operation=="Boolean"{assert_eq!(value.boolean().unwrap(),row["expected"].as_bool().unwrap())}else{let selected=match operation{"SequenceChild"=>value.sequence_child(index).unwrap(),"RecordChild"=>value.record_child(index).unwrap(),_=>&value};assert_eq!(selected.number().unwrap().as_f64(),row["expected"].as_f64().unwrap())}}}

#[test]fn primitive_scalar_work_includes_source_access_and_conversion(){use crate::owned::tree::NativeScalarValue;let input=DslValue::Bool(true);assert_eq!(<bool as NativeScalarValue<DslValue>>::read_work_demand(&input).unwrap(),2);assert!(<bool as NativeScalarValue<DslValue>>::read(&input).unwrap());}
